<?php
require_once 'config/layout.php';require_once 'config/guidance.php';require_login();$uid=(int)current_user()['id'];$p=profile_payload($uid);$a=latest_assessment($uid);if($a)$p['riasec_scores']=json_array($a['riasec_scores']);
$chosen=[];$error='';$data=null;if(is_string($_GET['career']??null))$chosen[]=$_GET['career'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);try{for($i=0;$i<3;$i++){ $v=input_text('career'.$i,160);if($v!=='')$chosen[]=$v;}$chosen=array_values(array_unique($chosen));if(!$chosen)throw new InvalidArgumentException('Choose at least one career.');$data=api_request('/compare',array_merge($p,['career_titles'=>$chosen]));if(!$data)$error='The comparison service is unavailable. Check your profile entries and try again.';elseif($data['unknown_titles']??[])$error='Choose career titles from the reference list: '.implode(', ',$data['unknown_titles']);}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}
page_start('Compare careers','careers');
?>
<main id="main" class="wide page-space"><div class="page-intro"><h1>Compare up to three careers</h1><p>Interest alignment, academic preparation and education pathways answer different questions. Missing information is shown as unknown.</p></div><?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?><section class="panel"><form method="post" class="form-grid"><?= csrf_field() ?><div class="three-grid"><?php for($i=0;$i<3;$i++):?><label>Career <?= $i+1 ?><input list="career-titles" name="career<?= $i ?>" maxlength="160" value="<?= e($chosen[$i]??'') ?>" <?= $i===0?'required':'' ?>></label><?php endfor;?></div><?php career_options();?><button class="btn btn-primary">Compare these careers</button></form></section>
<?php if($data):?><div class="compare-grid"><?php foreach($data['careers'] as $r): $supplement=career_supplement($r['title']); if($supplement){foreach(['skills','typical_activities'] as $field)if(!empty($supplement[$field]))$r[$field]=$supplement[$field];}?><article class="panel"><h2><?= e($r['title']) ?></h2><dl><?php foreach(['interest_alignment'=>'Interest alignment','academic_preparation'=>'Academic preparation','subject_compatibility'=>'Subject compatibility'] as $key=>$label):?><dt><?= e($label) ?></dt><dd><?= isset($r[$key])?e((string)$r[$key]).'%':'Unknown' ?></dd><?php endforeach;?><dt>Qualification reference (international)</dt><dd><?= e($r['education_level']??'Unknown') ?></dd><dt>Useful subjects (general guidance)</dt><dd><?= e($r['recommended_subjects']??'Not mapped') ?></dd><dt>Skills and activities</dt><dd><?= e(implode(', ',$r['skills']??[]).' · '.implode(', ',$r['typical_activities']??[]).' (RIASEC exploration prompts; not occupation-specific task evidence)') ?></dd><dt>Local pathways</dt><dd><?= e($r['pathway']??'Check the education directory') ?></dd><dt>Verified Lesotho labour-market information</dt><dd>No current occupation-specific dataset available. No employment forecast is made.</dd></dl><p><?= e($r['explanation']) ?></p><?php if($supplement):?><p><?= e($supplement['verification_scope']) ?> <?= source_link($supplement) ?></p><?php endif;?><?= saved_button('career',$r['title'],$r['title']) ?><p><a href="roadmap.php?career=<?= e(urlencode($r['title'])) ?>">Build a roadmap ↗</a></p></article><?php endforeach;?></div><?php endif;?></main><?php page_end(); ?>


